-- ===== sql/mysql/hm-pay-mp.sql =====
-- Enabled pay/mp schema derived from the pinned upstream data objects.
-- The pinned upstream base SQL includes system/infra only. No demo accounts or payment credentials are seeded.

CREATE TABLE `pay_app` (
  `id` BIGINT PRIMARY KEY AUTO_INCREMENT,
  `app_key` VARCHAR(255) NULL,
  `name` VARCHAR(255) NULL,
  `status` INT NULL,
  `remark` TEXT NULL,
  `order_notify_url` TEXT NULL,
  `refund_notify_url` TEXT NULL,
  `transfer_notify_url` TEXT NULL,
  `tenant_id` BIGINT NOT NULL DEFAULT 0,
  `creator` VARCHAR(64) NOT NULL DEFAULT '',
  `updater` VARCHAR(64) NOT NULL DEFAULT '',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted` BOOLEAN NOT NULL DEFAULT FALSE,
  KEY `idx_pay_app_tenant` (`tenant_id`),
  UNIQUE KEY `uk_pay_app_key` (`tenant_id`,`app_key`,`deleted`)
);

CREATE TABLE `pay_channel` (
  `id` BIGINT PRIMARY KEY AUTO_INCREMENT,
  `code` VARCHAR(255) NULL,
  `status` INT NULL,
  `fee_rate` DECIMAL(18,6) NULL,
  `remark` TEXT NULL,
  `app_id` BIGINT NULL,
  `config` TEXT NULL,
  `tenant_id` BIGINT NOT NULL DEFAULT 0,
  `creator` VARCHAR(64) NOT NULL DEFAULT '',
  `updater` VARCHAR(64) NOT NULL DEFAULT '',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted` BOOLEAN NOT NULL DEFAULT FALSE,
  KEY `idx_pay_channel_tenant` (`tenant_id`)
);

CREATE TABLE `pay_demo_order` (
  `id` BIGINT PRIMARY KEY AUTO_INCREMENT,
  `user_id` BIGINT NULL,
  `spu_id` BIGINT NULL,
  `spu_name` TEXT NULL,
  `price` INT NULL,
  `pay_status` BOOLEAN NULL,
  `pay_order_id` BIGINT NULL,
  `pay_time` DATETIME NULL,
  `pay_channel_code` TEXT NULL,
  `pay_refund_id` BIGINT NULL,
  `refund_price` INT NULL,
  `refund_time` DATETIME NULL,
  `tenant_id` BIGINT NOT NULL DEFAULT 0,
  `creator` VARCHAR(64) NOT NULL DEFAULT '',
  `updater` VARCHAR(64) NOT NULL DEFAULT '',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted` BOOLEAN NOT NULL DEFAULT FALSE,
  KEY `idx_pay_demo_order_tenant` (`tenant_id`)
);

CREATE TABLE `pay_demo_withdraw` (
  `id` BIGINT PRIMARY KEY AUTO_INCREMENT,
  `subject` TEXT NULL,
  `price` INT NULL,
  `user_account` TEXT NULL,
  `user_name` TEXT NULL,
  `type` INT NULL,
  `status` INT NULL,
  `pay_transfer_id` BIGINT NULL,
  `transfer_channel_code` TEXT NULL,
  `transfer_time` DATETIME NULL,
  `transfer_error_msg` TEXT NULL,
  `tenant_id` BIGINT NOT NULL DEFAULT 0,
  `creator` VARCHAR(64) NOT NULL DEFAULT '',
  `updater` VARCHAR(64) NOT NULL DEFAULT '',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted` BOOLEAN NOT NULL DEFAULT FALSE,
  KEY `idx_pay_demo_withdraw_tenant` (`tenant_id`)
);

CREATE TABLE `pay_notify_log` (
  `id` BIGINT PRIMARY KEY AUTO_INCREMENT,
  `task_id` BIGINT NULL,
  `notify_times` INT NULL,
  `response` TEXT NULL,
  `status` INT NULL,
  `tenant_id` BIGINT NOT NULL DEFAULT 0,
  `creator` VARCHAR(64) NOT NULL DEFAULT '',
  `updater` VARCHAR(64) NOT NULL DEFAULT '',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted` BOOLEAN NOT NULL DEFAULT FALSE,
  KEY `idx_pay_notify_log_tenant` (`tenant_id`)
);

CREATE TABLE `pay_notify_task` (
  `id` BIGINT PRIMARY KEY AUTO_INCREMENT,
  `app_id` BIGINT NULL,
  `type` INT NULL,
  `data_id` BIGINT NULL,
  `merchant_order_id` VARCHAR(255) NULL,
  `merchant_refund_id` VARCHAR(255) NULL,
  `merchant_transfer_id` TEXT NULL,
  `status` INT NULL,
  `next_notify_time` DATETIME NULL,
  `last_execute_time` DATETIME NULL,
  `notify_times` INT NULL,
  `max_notify_times` INT NULL,
  `notify_url` TEXT NULL,
  `tenant_id` BIGINT NOT NULL DEFAULT 0,
  `creator` VARCHAR(64) NOT NULL DEFAULT '',
  `updater` VARCHAR(64) NOT NULL DEFAULT '',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted` BOOLEAN NOT NULL DEFAULT FALSE,
  KEY `idx_pay_notify_task_tenant` (`tenant_id`)
);

CREATE TABLE `pay_order` (
  `id` BIGINT PRIMARY KEY AUTO_INCREMENT,
  `app_id` BIGINT NULL,
  `channel_id` BIGINT NULL,
  `channel_code` TEXT NULL,
  `user_id` BIGINT NULL,
  `user_type` INT NULL,
  `merchant_order_id` VARCHAR(255) NULL,
  `subject` TEXT NULL,
  `body` TEXT NULL,
  `notify_url` TEXT NULL,
