-- Apply once after V009. Existing aftersales remain refund requests.
ALTER TABLE hm_aftersale MODIFY COLUMN amount_cents INT NULL;
ALTER TABLE hm_aftersale ADD COLUMN type VARCHAR(24) NOT NULL DEFAULT 'PARTIAL_REFUND';
ALTER TABLE hm_aftersale ADD COLUMN request_key VARCHAR(100) NULL;
ALTER TABLE hm_aftersale ADD COLUMN resolution VARCHAR(1000) NOT NULL DEFAULT '';
ALTER TABLE hm_aftersale ADD COLUMN assigned_worker_id BIGINT NULL;
ALTER TABLE hm_aftersale ADD COLUMN remedy_booking_id BIGINT NULL;
ALTER TABLE hm_aftersale ADD COLUMN scheduled_at DATETIME NULL;
ALTER TABLE hm_aftersale ADD COLUMN processed_at DATETIME NULL;
ALTER TABLE hm_aftersale ADD COLUMN closed_at DATETIME NULL;
ALTER TABLE hm_aftersale ADD COLUMN refund_attempt INT NOT NULL DEFAULT 0;
ALTER TABLE hm_aftersale ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE hm_aftersale ADD CONSTRAINT chk_aftersale_type CHECK(type IN ('REWORK','REASSIGN_WORKER','REVISIT','PARTIAL_REFUND','FULL_REFUND','OTHER_COMPENSATION'));
ALTER TABLE hm_aftersale ADD CONSTRAINT chk_aftersale_status CHECK(status IN ('REQUESTED','SCHEDULED','IN_PROGRESS','AWAITING_CONFIRMATION','REFUNDING','REFUNDED','COMPLETED','REJECTED','CANCELLED','FAILED','MIGRATION_REVIEW'));
ALTER TABLE hm_aftersale ADD CONSTRAINT chk_aftersale_amount CHECK((type IN ('PARTIAL_REFUND','FULL_REFUND') AND amount_cents>0) OR (type IN ('REWORK','REASSIGN_WORKER','REVISIT','OTHER_COMPENSATION') AND amount_cents IS NULL));
CREATE UNIQUE INDEX uk_aftersale_request ON hm_aftersale(tenant_id,customer_id,request_key);
ALTER TABLE hm_booking ADD COLUMN aftersale_id BIGINT NULL;
CREATE UNIQUE INDEX uk_booking_aftersale ON hm_booking(tenant_id,aftersale_id);
CREATE TABLE hm_aftersale_log (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, aftersale_id BIGINT NOT NULL, order_id BIGINT NOT NULL,
 action VARCHAR(40) NOT NULL, from_status VARCHAR(30) NULL, to_status VARCHAR(30) NOT NULL,
 actor_id BIGINT NULL, actor_type INT NULL, detail VARCHAR(1000) NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY idx_aftersale_log(tenant_id,aftersale_id,id), KEY idx_aftersale_order_log(tenant_id,order_id,id)
);
 SELECT tenant_id,id,order_id,'MIGRATED',NULL,status,'升级前售后记录',created_at FROM hm_aftersale;
SELECT r.id,901130,r.tenant_id,'migration','migration',FALSE FROM system_role r
WHERE r.deleted=FALSE AND r.code IN ('super_admin','hm_platform','hm_owner','hm_manager','hm_support')
AND NOT EXISTS (SELECT 1 FROM system_role_menu x WHERE x.role_id=r.id AND x.menu_id=901130 AND x.tenant_id=r.tenant_id AND x.deleted=FALSE);

-- ===== sql/mysql/upgrades/V011__complete_reviews.sql =====
-- Apply once after V010. Existing reviews remain published and keep their original rating.
ALTER TABLE hm_review ADD COLUMN service_rating INT NOT NULL DEFAULT 5;
ALTER TABLE hm_review ADD COLUMN worker_rating INT NOT NULL DEFAULT 5;
ALTER TABLE hm_review ADD COLUMN tags_json VARCHAR(1000) NOT NULL DEFAULT '[]';
ALTER TABLE hm_review ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'PUBLISHED';
ALTER TABLE hm_review ADD COLUMN reply_content VARCHAR(1000) NULL;
ALTER TABLE hm_review ADD COLUMN replied_by BIGINT NULL;
ALTER TABLE hm_review ADD COLUMN replied_at DATETIME NULL;
ALTER TABLE hm_review ADD COLUMN recommended BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE hm_review ADD COLUMN updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
UPDATE hm_review SET service_rating=rating,worker_rating=rating,status='PUBLISHED';
ALTER TABLE hm_review ADD CONSTRAINT chk_review_service_rating CHECK(service_rating BETWEEN 1 AND 5);
ALTER TABLE hm_review ADD CONSTRAINT chk_review_worker_rating CHECK(worker_rating BETWEEN 1 AND 5);
ALTER TABLE hm_review ADD CONSTRAINT chk_review_status CHECK(status IN ('DRAFT','PUBLISHED'));
CREATE INDEX idx_review_display ON hm_review(tenant_id,status,visible,recommended,id);
CREATE TABLE hm_review_image (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, review_id BIGINT NOT NULL,
 storage_key VARCHAR(200) NOT NULL, content_type VARCHAR(40) NOT NULL, request_key VARCHAR(100) NOT NULL,
 sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uk_review_image_request(tenant_id,review_id,request_key), KEY idx_review_image(tenant_id,review_id,sort_order,id)
);
CREATE TABLE hm_review_log (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, review_id BIGINT NOT NULL, order_id BIGINT NOT NULL,
 action VARCHAR(40) NOT NULL, actor_id BIGINT NULL, actor_type VARCHAR(20) NOT NULL,
 detail TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY idx_review_log(tenant_id,review_id,id), KEY idx_review_order_log(tenant_id,order_id,id)
);
 SELECT tenant_id,id,order_id,'MIGRATED','SYSTEM','升级前评价记录',created_at FROM hm_review;
SELECT r.id,901140,r.tenant_id,'migration','migration',FALSE FROM system_role r
WHERE r.deleted=FALSE AND r.code IN ('super_admin','hm_platform','hm_owner','hm_manager','hm_support')
AND NOT EXISTS (SELECT 1 FROM system_role_menu x WHERE x.role_id=r.id AND x.menu_id=901140 AND x.tenant_id=r.tenant_id AND x.deleted=FALSE);

-- ===== sql/mysql/upgrades/V012__franchise_contract_center.sql =====
-- Apply once after V011. Franchise records are platform data linked to, but not stored in, system_tenant.
CREATE TABLE hm_franchisee (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, tenant_id BIGINT NOT NULL, code VARCHAR(40) NOT NULL,
 company_name VARCHAR(160) NOT NULL, credit_code VARCHAR(32) NOT NULL DEFAULT '', leader_name VARCHAR(80) NOT NULL,
 leader_mobile_ciphertext VARCHAR(500) NOT NULL, leader_mobile_last4 CHAR(4) NOT NULL,
 contact_email VARCHAR(160) NOT NULL DEFAULT '', registered_address VARCHAR(500) NOT NULL DEFAULT '',
 settlement_account_name VARCHAR(160) NOT NULL, settlement_bank_name VARCHAR(160) NOT NULL,
 settlement_account_ciphertext VARCHAR(500) NOT NULL, settlement_account_last4 VARCHAR(4) NOT NULL,
 status VARCHAR(20) NOT NULL DEFAULT 'PENDING', version BIGINT NOT NULL DEFAULT 0,
 created_by BIGINT NOT NULL, updated_by BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 terminated_by BIGINT NULL, terminated_at DATETIME NULL, termination_reason VARCHAR(500) NOT NULL DEFAULT '',
 UNIQUE KEY uk_franchise_tenant(tenant_id), UNIQUE KEY uk_franchise_code(code),
 KEY idx_franchise_status(status,id),
 CONSTRAINT chk_franchise_status CHECK(status IN ('PENDING','ACTIVE','SUSPENDED','TERMINATED'))
);
CREATE TABLE hm_franchise_region (
 franchisee_id BIGINT NOT NULL, tenant_id BIGINT NOT NULL, region_code VARCHAR(32) NOT NULL,
 region_name VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(franchisee_id,region_code), KEY idx_franchise_region_tenant(tenant_id,region_code)
);
CREATE TABLE hm_franchise_contract (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, franchisee_id BIGINT NOT NULL, tenant_id BIGINT NOT NULL,
 contract_no VARCHAR(60) NOT NULL, signed_on DATE NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL,
 deposit_cents BIGINT NOT NULL DEFAULT 0, deposit_status VARCHAR(20) NOT NULL DEFAULT 'NOT_REQUIRED',
 status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', previous_contract_id BIGINT NULL,
 remark VARCHAR(1000) NOT NULL DEFAULT '', version BIGINT NOT NULL DEFAULT 0,
 created_by BIGINT NOT NULL, updated_by BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 activated_by BIGINT NULL, activated_at DATETIME NULL, terminated_by BIGINT NULL, terminated_at DATETIME NULL,
 termination_reason VARCHAR(500) NOT NULL DEFAULT '',
 UNIQUE KEY uk_franchise_contract_no(contract_no), KEY idx_franchise_contract(franchisee_id,status,start_date,end_date),
 KEY idx_franchise_contract_tenant(tenant_id,status,end_date),
 CONSTRAINT chk_franchise_contract_dates CHECK(end_date>=start_date),
 CONSTRAINT chk_franchise_contract_deposit CHECK(deposit_cents>=0),
 CONSTRAINT chk_franchise_contract_status CHECK(status IN ('DRAFT','ACTIVE','EXPIRED','TERMINATED')),
 CONSTRAINT chk_franchise_deposit_status CHECK(deposit_status IN ('NOT_REQUIRED','PENDING','PAID','REFUNDED','FORFEITED'))
);
CREATE TABLE hm_franchise_deposit_entry (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, franchisee_id BIGINT NOT NULL, contract_id BIGINT NOT NULL,
 tenant_id BIGINT NOT NULL, entry_type VARCHAR(20) NOT NULL, amount_cents BIGINT NOT NULL,
 channel VARCHAR(24) NOT NULL, occurred_at DATETIME NOT NULL, reference_no VARCHAR(100) NOT NULL DEFAULT '',
 request_key VARCHAR(80) NOT NULL, operator_id BIGINT NOT NULL, note VARCHAR(500) NOT NULL DEFAULT '',
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uk_franchise_deposit_request(contract_id,request_key),
 KEY idx_franchise_deposit(contract_id,id), KEY idx_franchise_deposit_tenant(tenant_id,occurred_at),
 CONSTRAINT chk_franchise_deposit_type CHECK(entry_type IN ('RECEIPT','REFUND','FORFEIT')),
 CONSTRAINT chk_franchise_deposit_amount CHECK(amount_cents>0)
);
CREATE TABLE hm_franchise_audit_log (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, action VARCHAR(40) NOT NULL, franchisee_id BIGINT NOT NULL,
 contract_id BIGINT NULL, tenant_id BIGINT NOT NULL, actor_id BIGINT NOT NULL,
 before_json TEXT NOT NULL, after_json TEXT NOT NULL, reason VARCHAR(500) NOT NULL DEFAULT '',
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY idx_franchise_audit(franchisee_id,id), KEY idx_franchise_audit_tenant(tenant_id,id)
);
SELECT r.id,m.id,r.tenant_id,'migration','migration',FALSE FROM system_role r CROSS JOIN system_menu m
WHERE r.deleted=FALSE AND r.code IN ('super_admin','hm_platform') AND m.id IN (900009,901150,901151,901152)
AND NOT EXISTS(SELECT 1 FROM system_role_menu x WHERE x.role_id=r.id AND x.tenant_id=r.tenant_id AND x.menu_id=m.id AND x.deleted=FALSE);
